#import <Foundation/Foundation.h>
#import "app/LinuxRunner/RFBClient.h"
static NSData *pixels; static uint16_t width,height; static BOOL failed;
static void pauseRun(double sec){NSDate *end=[NSDate dateWithTimeIntervalSinceNow:sec];while([end timeIntervalSinceNow]>0)[NSRunLoop.currentRunLoop runUntilDate:[NSDate dateWithTimeIntervalSinceNow:.1]];}
// This fixture installs Ubuntu's known wallpaper and dock. A mapped window or
// a delivered framebuffer is not sufficient evidence when the viewer is black.
// This is a test oracle, not a production readiness or wallpaper-colour rule.
static BOOL visibleFrame(NSData *frame){const uint8_t *p=frame.bytes;NSUInteger n=frame.length, visible=0, threshold=n/400, distinct=0;BOOL bins[512]={0};if(threshold<512)threshold=512;for(NSUInteger i=0;i+3<n;i+=4){if(p[i]||p[i+1]||p[i+2])visible++;if(i%64==0){unsigned bin=((p[i]>>5)<<6)|((p[i+1]>>5)<<3)|(p[i+2]>>5);if(!bins[bin]){bins[bin]=YES;distinct++;}}if(visible>=threshold&&distinct>=8)return YES;}return NO;}
int main(int argc,char **argv){@autoreleasepool{
 if(argc!=5)return 2;NSString *out=@(argv[3]);NSString *session=[@(getenv("LR_GUI_APPLICATION_LOG")) stringByDeletingLastPathComponent];NSString *root=[[[session stringByDeletingLastPathComponent] stringByDeletingLastPathComponent] stringByDeletingLastPathComponent];NSString *status=[session stringByAppendingPathComponent:@"desktop-state"];
 NSString *password=[NSString stringWithContentsOfFile:@(argv[2]) encoding:NSASCIIStringEncoding error:nil];LRRFBClient *c=[[LRRFBClient alloc]initWithPort:atoi(argv[1]) password:password];
 c.frameHandler=^(NSData*d,uint16_t w,uint16_t h,uint64_t frames,uint64_t bytes){dispatch_async(dispatch_get_main_queue(),^{pixels=[d copy];width=w;height=h;});};
 c.statusHandler=^(NSString*s){if([s hasPrefix:@"Display error:"])failed=YES;};[c start];BOOL ready=NO;
 for(int i=0;i<480&&!failed;i++){pauseRun(.25);NSString *s=[NSString stringWithContentsOfFile:status encoding:NSUTF8StringEncoding error:nil];if([s containsString:@"ready=1"]&&pixels){ready=YES;break;}if([NSFileManager.defaultManager fileExistsAtPath:[session stringByAppendingPathComponent:@"stop"]])break;}
 if(ready){for(int i=0;i<100&&!visibleFrame(pixels);i++)pauseRun(.2);NSString *log=[NSString stringWithContentsOfFile:[session stringByAppendingPathComponent:@"application.log"] encoding:NSUTF8StringEncoding error:nil]; if(!visibleFrame(pixels)){fprintf(stderr,"GNOME_VIEWER_BLACK_FRAME\n");ready=NO;} if([NSFileManager.defaultManager fileExistsAtPath:[session stringByAppendingPathComponent:@"stop"]] || [log containsString:@"Segmentation fault"] || [log containsString:@"Trace/breakpoint trap"])ready=NO;}
 if(ready){[pixels writeToFile:[out stringByAppendingPathComponent:@"gnome.bgra"] atomically:YES];NSString *meta=[NSString stringWithFormat:@"%u %u\n",width,height];[meta writeToFile:[out stringByAppendingPathComponent:@"gnome-frame-size"] atomically:YES encoding:NSUTF8StringEncoding error:nil]; [c pointerX:width/2 y:height-28 buttons:0]; pauseRun(.3); [c pointerX:width/2 y:height-28 buttons:1]; pauseRun(.2); [c pointerX:width/2 y:height-28 buttons:0]; pauseRun(8); [pixels writeToFile:[out stringByAppendingPathComponent:@"gnome-apps.bgra"] atomically:YES]; [c pointerX:430 y:235 buttons:0]; pauseRun(.3); [c pointerX:430 y:235 buttons:1]; pauseRun(.2); [c pointerX:430 y:235 buttons:0]; pauseRun(12); [pixels writeToFile:[out stringByAppendingPathComponent:@"gnome-terminal.bgra"] atomically:YES]; [c pointerX:32 y:65 buttons:0]; pauseRun(.3); [c pointerX:32 y:65 buttons:1]; pauseRun(.2); [c pointerX:32 y:65 buttons:0]; BOOL mapped=NO; for(int i=0;i<240&&!mapped;i++){pauseRun(.5); NSString *windows=[NSString stringWithContentsOfFile:[session stringByAppendingPathComponent:@"window.log"] encoding:NSUTF8StringEncoding error:nil]; for(NSString *line in [windows componentsSeparatedByString:@"\n"]) if([line containsString:@"viewable=yes"] && [line containsString:@"class=org.gnome.Nautilus title=Home"]) {mapped=YES;break;}} if(mapped){pauseRun(10);[pixels writeToFile:[out stringByAppendingPathComponent:@"gnome-files.bgra"] atomically:YES];if(!visibleFrame(pixels)){fprintf(stderr,"GNOME_FILES_BLACK_FRAME\n");ready=NO;}} else {fprintf(stderr,"GNOME_FILES_WINDOW_MISSING\n");ready=NO;}}
 [c stop];fprintf(stderr,"GNOME_PROBE_%s\n",ready?"PASS":"FAIL");return ready?0:1;
}}
